package com.campusconnect.model;
import java.time.LocalDate;
public class LostFoundItem { private int id,postedBy; private String title,description,category,location,status,posterName; private LocalDate itemDate;
 public LostFoundItem(){} public int getId(){return id;} public void setId(int v){id=v;} public int getPostedBy(){return postedBy;} public void setPostedBy(int v){postedBy=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getPosterName(){return posterName;} public void setPosterName(String v){posterName=v;} public LocalDate getItemDate(){return itemDate;} public void setItemDate(LocalDate v){itemDate=v;}}
